/// Parses `nvidia-smi` output to extract GPU metrics.
use anyhow::{Context, Result};
use std::process::Command;
use tracing::{debug, warn};

use crate::models::GpuMetric;

/// Query structured GPU data via nvidia-smi CSV mode (no header).
pub fn query_gpu(device_index: usize) -> Result<GpuMetric> {
    let output = Command::new("nvidia-smi")
        .args([
            "--query-gpu=index,name,temperature.gpu,memory.used,memory.total,utilization.gpu,power.draw",
            "--format=csv,noheader,nounits",
            "--id",
            &device_index.to_string(),
        ])
        .output()
        .context("Failed to execute nvidia-smi (is it installed?). Using placeholder GPU metrics.")?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        anyhow::bail!("nvidia-smi failed: {}", stderr.trim());
    }

    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    debug!("nvidia-smi raw output: {}", stdout);

    parse_gpu_csv_line(&stdout, device_index)
}

/// Best-effort GPU query — returns a placeholder metric on failure.
pub fn try_query_gpu(device_index: usize) -> GpuMetric {
    match query_gpu(device_index) {
        Ok(metric) => metric,
        Err(e) => {
            warn!(
                "GPU query failed (this is expected in non-GPU dev environments): {}",
                e
            );
            GpuMetric::placeholder()
        }
    }
}

/// Parse a single CSV line from `nvidia-smi --query-... --format=csv,noheader,nounits`.
/// Expected columns: index, name, temp, mem_used, mem_total, util_gpu, power_draw
fn parse_gpu_csv_line(line: &str, expected_index: usize) -> Result<GpuMetric> {
    // nvidia-smi output has fields separated by ", ". GPU name can contain commas
    // but since we query a specific device by --id, there is exactly one line.
    // We split from the right for numeric fields and treat the middle as name.

    let parts: Vec<&str> = line.split(", ").collect();

    if parts.len() < 7 {
        anyhow::bail!("Unexpected nvidia-smi CSV fields count: {}", parts.len());
    }

    // Parse from right for numeric fields, name is everything between index and temperature.
    let power = parse_optional_f64(parts.last().copied());
    let utilization = parse_optional_f64(parts.get(parts.len() - 2).copied());
    let mem_total_raw = parts.get(parts.len() - 3).copied();
    let mem_used_raw = parts.get(parts.len() - 4).copied();
    let temp = parse_optional_f64(parts.get(parts.len() - 5).copied());

    // Name is in the middle (from index 1 to len-6)
    let name_fields: Vec<_> = parts[1..parts.len() - 6].to_vec();
    let name = if !name_fields.is_empty() {
        Some(name_fields.join(", "))
    } else {
        None
    };

    let idx_parsed = parts.first().and_then(|s| s.trim().parse::<usize>().ok());
    if Some(expected_index) != idx_parsed {
        anyhow::bail!(
            "GPU index mismatch: expected {}, got {:?}",
            expected_index,
            idx_parsed
        );
    }

    let mem_used = parse_optional_u64(mem_used_raw);
    let mem_total = parse_optional_u64(mem_total_raw);

    let remaining = match (mem_used, mem_total) {
        (Some(u), Some(t)) => Some(t.saturating_sub(u)),
        _ => None,
    };

    Ok(GpuMetric {
        name,
        temperature_c: temp,
        memory_used_mib: mem_used,
        memory_total_mib: mem_total,
        memory_remaining_mib: remaining,
        utilization_pct: utilization,
        power_watts: power,
    })
}

fn parse_optional_f64(s: Option<&str>) -> Option<f64> {
    s.and_then(|v| v.trim().parse::<f64>().ok())
}

fn parse_optional_u64(s: Option<&str>) -> Option<u64> {
    s.and_then(|v| v.trim().parse::<u64>().ok())
}

/// Shared data types for Ollama and GPU state.
use serde::{Deserialize, Serialize};

// ── Ollama API response types ───────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OllamaTagsResponse {
    pub models: Vec<OllamaModelEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OllamaModelEntry {
    #[serde(rename = "name")]
    pub model_name: String,
    #[serde(rename = "size")]
    pub size_bytes: Option<u64>,
    #[serde(rename = "digest")]
    pub digest: Option<String>,
    #[serde(rename = "modified_at")]
    pub modified_at: Option<String>,
}

// ── Aggregated status (exposed by REST API) ─────────────────────

#[derive(Debug, Clone, Serialize)]
pub struct MonitorStatus {
    pub ollama_url: String,
    pub ollama_reachable: bool,
    pub loaded_model: Option<String>,
    pub available_models: Vec<String>,
    pub gpu: GpuMetric,
    pub timestamp: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct GpuMetric {
    pub name: Option<String>,
    pub temperature_c: Option<f64>,
    pub memory_used_mib: Option<u64>,
    pub memory_total_mib: Option<u64>,
    pub memory_remaining_mib: Option<u64>,
    pub utilization_pct: Option<f64>,
    pub power_watts: Option<f64>,
}

impl GpuMetric {
    pub fn placeholder() -> Self {
        Self {
            name: None,
            temperature_c: None,
            memory_used_mib: None,
            memory_total_mib: None,
            memory_remaining_mib: None,
            utilization_pct: None,
            power_watts: None,
        }
    }
}

// ── Web API response types (subset views) ──────────────────────

#[derive(Debug, Clone, Serialize)]
pub struct ApiModelResponse {
    pub loaded_model: Option<String>,
    pub available_models: Vec<String>,
    pub total_count: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct ApiGpuResponse {
    pub gpu: GpuMetric,
    pub timestamp: String,
}

/// Application-wide configuration loaded from environment variables with sensible defaults.
///
/// Environment variables:
///
/// | Variable                  | Default               | Description                        |
/// |---------------------------|-----------------------|------------------------------------|
/// | `OLLAMA_HOST`             | `http://127.0.0.1`      | Ollama server base URL             |
/// | `OLLAMA_PORT`             | `11434`               | Ollama server port                 |
/// | `SERVER_BIND`             | `0.0.0.0`             | Address to bind the API server to  |
/// | `SERVER_PORT`             | `3000`                | Port for the API server            |
/// | `REFRESH_INTERVAL_SECS`   | `15`                  | Seconds between status refreshes   |
/// | `GPU_DEVICE_INDEX`        | `0`                   | NVIDIA GPU device index to query   |

#[derive(Debug, Clone)]
pub struct Config {
    pub ollama_host: String,
    pub ollama_port: u16,
    pub server_bind: String,
    pub server_port: u16,
    pub refresh_interval_secs: u64,
    pub gpu_device_index: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            ollama_host: "http://127.0.0.1".into(),
            ollama_port: 11434,
            server_bind: "0.0.0.0".into(),
            server_port: 3000,
            refresh_interval_secs: 15,
            gpu_device_index: 0,
        }
    }
}

impl Config {
    /// Load config from environment variables, falling back to defaults for unset values.
    pub fn load() -> Self {
        let mut config = Self::default();

        if let Ok(val) = std::env::var("OLLAMA_HOST") {
            config.ollama_host = val;
        }
        if let Ok(val) = std::env::var("OLLAMA_PORT") {
            if let Ok(port) = val.parse::<u16>() {
                config.ollama_port = port;
            } else {
                tracing::warn!("Invalid OLLAMA_PORT '{}', using default", val);
            }
        }

        if let Ok(val) = std::env::var("SERVER_BIND") {
            config.server_bind = val;
        }
        if let Ok(val) = std::env::var("SERVER_PORT") {
            if let Ok(port) = val.parse::<u16>() {
                config.server_port = port;
            } else {
                tracing::warn!("Invalid SERVER_PORT '{}', using default", val);
            }
        }
        if let Ok(val) = std::env::var("REFRESH_INTERVAL_SECS") {
            if let Ok(interval) = val.parse::<u64>() {
                config.refresh_interval_secs = interval;
            } else {
                tracing::warn!("Invalid REFRESH_INTERVAL_SECS '{}', using default", val);
            }
        }

        if let Ok(val) = std::env::var("GPU_DEVICE_INDEX") {
            if let Ok(index) = val.parse::<usize>() {
                config.gpu_device_index = index;
            } else {
                tracing::warn!("Invalid GPU_DEVICE_INDEX '{}', using default", val);
            }
        }

        config
    }

    pub fn ollama_base_url(&self) -> String {
        format!("{}:{}", self.ollama_host, self.ollama_port)
    }
}

/// Client for the Ollama REST API.
use anyhow::{Context, Result};
use reqwest::Client;
use std::time::Duration;
use tracing::{debug, warn};

use crate::models::OllamaTagsResponse;

pub struct OllamaClient {
    base_url: String,
    http: Client,
}

impl OllamaClient {
    pub fn new(base_url: impl Into<String>) -> Self {
        Self {
            base_url: base_url.into(),
            http: Client::builder()
                .timeout(Duration::from_secs(10))
                .build()
                .expect("reqwest client build"),
        }
    }

    /// Fetch available models from `/api/tags`.
    pub async fn fetch_models(&self) -> Result<OllamaTagsResponse> {
        debug!("Fetching models from {}", self.base_url);
        let url = format!("{}/api/tags", self.base_url);

        self.http
            .get(&url)
            .send()
            .await
            .with_context(|| format!("Failed to connect to Ollama at {}", url))?
            .json::<OllamaTagsResponse>()
            .await
            .with_context(|| "Failed to parse Ollama /api/tags response")
    }

    /// Best-effort fetch; returns None on failure instead of propagating errors.
    pub async fn try_fetch_models(&self) -> Option<OllamaTagsResponse> {
        match self.fetch_models().await {
            Ok(resp) => Some(resp),
            Err(e) => {
                warn!("Ollama connection failed: {}", e);
                None
            }
        }
    }
}

