/// SQLite persistence for GPU history metrics.
use anyhow::Context;
use chrono::{DateTime, Utc};
use sqlx::{SqlitePool, sqlite::SqliteRow};
use std::time::Duration;
use tracing::{debug, info};

// ── Schema constants ─────────────────────────────────────

const CREATE_TABLE: &str = r#"
    CREATE TABLE IF NOT EXISTS gpu_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        recorded_at TEXT NOT NULL,
        memory_used_mib INTEGER,
        temperature_c REAL
    )
"#;

/// Prune rows older than 30 days (run during startup to avoid unbounded growth).
const VACUUM_SQL: &str = r#"
    DELETE FROM gpu_history
    WHERE recorded_at < datetime('now', '-30 days')
"#;

// ── Public types ─────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct GpuHistoryPoint {
    pub recorded_at: DateTime<Utc>,
    pub memory_used_mib: Option<u64>,
    pub temperature_c: Option<f64>,
}

/// Supported time ranges for the dashboard history view.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HistoryRange {
    LastHour,
    LastDay,
    LastWeek,
    LastMonth,
}

impl HistoryRange {
    /// Human-readable label shown in the UI selector.
    pub fn label(&self) -> &'static str {
        match self {
            HistoryRange::LastHour => "1 Hour",
            HistoryRange::LastDay => "24 Hours",
            HistoryRange::LastWeek => "7 Days",
            HistoryRange::LastMonth => "30 Days",
        }
    }

    /// SQLite-friendly interval string for `datetime('now', …)`.
    pub fn sqlite_interval(&self) -> &'static str {
        match self {
            HistoryRange::LastHour => "-1 hour",
            HistoryRange::LastDay => "-24 hours",
            HistoryRange::LastWeek => "-7 days",
            HistoryRange::LastMonth => "-30 days",
        }
    }
}

// ── Connection pool helpers ──────────────────────────────

/// Open (or create) the SQLite database and return a connection pool.
pub async fn open_pool(db_path: &str) -> anyhow::Result<SqlitePool> {
    // sqlx requires a DSN; for SQLite the path is the DSN itself.
    let dsn = format!("sqlite://{db_path}");
    let pool = SqlitePool::connect(&dsn)
        .await
        .context("Failed to connect to SQLite database")?;

    // Enable WAL mode for better concurrency and run auto-vacuum.
    sqlx::query("PRAGMA journal_mode=WAL;").execute(&pool).await.ok();
    sqlx::query("PRAGMA busy_timeout = 5000;").execute(&pool).await.ok();
    sqlx::query("PRAGMA auto_vacuum = FULL;").execute(&pool).await.ok();

    Ok(pool)
}

/// Run one-time schema migration (idempotent).
pub async fn migrate(pool: &SqlitePool) -> anyhow::Result<()> {
    sqlx::query(CREATE_TABLE)
        .execute(pool)
        .await
        .context("Failed to create gpu_history table")?;
    info!("Database schema ready");

    // Prune stale data.
    let deleted = sqlx::query(VACUUM_SQL)
        .execute(pool)
        .await
        .context("Failed to prune stale rows")?;
    if deleted.rows_affected() > 0 {
        debug!("Pruned {} stale history rows", deleted.rows_affected());
    }

    Ok(())
}

// ── Mutation ─────────────────────────────────────────────

/// Insert a single snapshot row.
pub async fn insert_snapshot(
    pool: &SqlitePool,
    memory_used_mib: Option<u64>,
    temperature_c: Option<f64>,
) -> anyhow::Result<()> {
    let now = Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true);

    sqlx::query(
        "INSERT INTO gpu_history (recorded_at, memory_used_mib, temperature_c) VALUES (?, ?, ?)",
    )
    .bind(now)
    .bind(memory_used_mib)
    .bind(temperature_c)
    .execute(pool)
    .await
    .context("Failed to insert gpu_history row")?;

    Ok(())
}

// ── Queries ──────────────────────────────────────────────

/// Fetch all history rows within the given range, ordered by time ascending.
pub async fn query_history(
    pool: &SqlitePool,
    range: HistoryRange,
) -> anyhow::Result<Vec<GpuHistoryPoint>> {
    let interval = range.sqlite_interval();

    let rows = sqlx::query::<SqliteRow>(
        "SELECT recorded_at, memory_used_mib, temperature_c \
         FROM gpu_history \
         WHERE recorded_at >= datetime('now', ?) \
         ORDER BY recorded_at ASC",
    )
    .bind(interval)
    .fetch_all(pool)
    .await
    .context("Failed to query gpu_history")?;

    let mut points = Vec::with_capacity(rows.len());
    for row in rows {
        let recorded_at_str: String = row.try_get("recorded_at")?;
        let recorded_at: DateTime<Utc> = DateTime::parse_from_rfc3339(&recorded_at_str)
            .context("Malformed timestamp in gpu_history")?
            .with_timezone(&Utc);

        let memory_used_mib: Option<i64> = row.try_get("memory_used_mib")?;
        let temperature_c: Option<f64> = row.try_get("temperature_c")?;

        points.push(GpuHistoryPoint {
            recorded_at,
            memory_used_mib: memory_used_mib.map(|v| v as u64),
            temperature_c,
        });
    }

    Ok(points)
}

